 * 负责初始化应用、设置路由、处理生命周期事件
 * @author Joker.X
 */
export default class EntryAbility extends UIAbility {
  /**
   * 应用创建时调用
   * 初始化应用上下文、设置颜色模式、注册路由
   * @param {Want} want - 启动意图
   * @param {AbilityConstant.LaunchParam} launchParam - 启动参数
   * @returns {void} 无返回值
   */
  onCreate(want: Want, launchParam: AbilityConstant.LaunchParam): void {
    try {
      this.context.getApplicationContext().setColorMode(ConfigurationConstant.ColorMode.COLOR_MODE_NOT_SET);
      this.registerRouter();
      ContextUtil.init(this.context)
    } catch (err) {
      hilog.error(DOMAIN, 'testTag', 'Failed to set colorMode. Cause: %{public}s', JSON.stringify(err));
    }
    hilog.info(DOMAIN, 'testTag', '%{public}s', 'Ability onCreate');
  }

  /**
   * 窗口创建时调用
   * 加载入口页面、初始化UI基础样式
   * @param {window.WindowStage} windowStage - 窗口阶段
   * @returns {Promise<void>} 无返回值的Promise
   */
  async onWindowStageCreate(windowStage: window.WindowStage): Promise<void> {
    await this.initIBestORM();
    const fixtureAuth: Auth = new Auth();
    fixtureAuth.token = "fixture28-public-identity";
    fixtureAuth.expire = 86400;
    const fixtureUser: User = new User();
    fixtureUser.id = 28;
    fixtureUser.nickName = "Fixture28";
    fixtureUser.phone = "13800000028";
    fixtureUser.avatarUrl = "";
    getUserState().updateUserState(fixtureAuth, fixtureUser);
    await new TokenStoreRepository().saveToken(fixtureAuth.token);
    windowStage.loadContent('view/EntryPage', (_) => {
      IBestUIInitializer.initIBestUI(windowStage, this.context);
    });
  }

  /**
   * 应用销毁时调用
   * 释放应用上下文、注销路由
   * @returns {void} 无返回值
   */
  onDestroy(): void {
    hilog.info(DOMAIN, 'testTag', '%{public}s', 'Ability onDestroy');
  }

  /**
   * 窗口销毁时调用
   * 释放窗口资源
   * @returns {void} 无返回值
   */
  onWindowStageDestroy(): void {
  }

  /**
   * 应用进入前台时调用
   * 刷新应用状态、重新注册路由
   * @returns {void} 无返回值
   */
  onForeground(): void {
  }

  /**
   * 应用进入后台时调用
   * 暂停应用状态、注销路由
   * @returns {void} 无返回值
   */
  onBackground(): void {
  }

  /**
   * 初始化 IBest ORM 数据库
import { AxiosInstance, AxiosResponse, InternalAxiosRequestConfig, AxiosError, AxiosHeaders } from "@ohos/axios";
import { TokenStoreDataSource, TokenStoreDataSourceImpl } from "datastore";
import { setupLogInterceptor } from "./LogInterceptor";

/**
 * @file 全局网络拦截器注册
 * @author Joker.X
 */

/**
 * 配置全局网络拦截器
 * @param {AxiosInstance} axiosInstance - Axios 实例
 * @returns {void} 无返回值
 */
export function setupInterceptors(axiosInstance: AxiosInstance): void {
  setupLogInterceptor(axiosInstance);

  // 请求拦截器
  axiosInstance.interceptors.request.use(
    async (config: InternalAxiosRequestConfig): Promise<InternalAxiosRequestConfig> => {
      const tokenStore: TokenStoreDataSource = new TokenStoreDataSourceImpl();
      const token: string = await tokenStore.getToken();
      if (token) {
        const headers: AxiosHeaders = AxiosHeaders.from(config.headers);
        headers.set("Authorization", token);
        config.headers = headers;
      }
      return config;
    },
    (error: AxiosError) => {
      return Promise.reject(error);
    }
  );

  // 响应拦截器
  axiosInstance.interceptors.response.use(
    (response: AxiosResponse) => {
      return response;
    },
    (error: AxiosError) => {
      return Promise.reject(error);
    }
  );
}
"}

